package com.nexusdrive.metadata.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="file_versions")public class FileVersion{@Id private UUID id;@ManyToOne(optional=false,fetch=FetchType.LAZY)@JoinColumn(name="file_id")private FileMetadata file;@Column(name="version_number",nullable=false)private int versionNumber;@Column(name="size_bytes",nullable=false)private long sizeBytes;@Column(name="content_hash",nullable=false,length=64)private String contentHash;@Column(name="created_at",nullable=false)private Instant createdAt;@PrePersist void pre(){if(id==null)id=UUID.randomUUID();createdAt=Instant.now();}public void setFile(FileMetadata v){file=v;}public void setVersionNumber(int v){versionNumber=v;}public void setSizeBytes(long v){sizeBytes=v;}public void setContentHash(String v){contentHash=v;}}
